import { ref, onMounted } from 'vue';
import { useAuthTokenStore } from 'src/store/main';
import { getOrgId } from 'src/utils/organization/org_id_helper';

/**
 * Composable for Image Authentication
 *
 * Provides reactive token query parameters for authenticated image requests.
 * Integrates with the Auth SDK through the auth token store.
 *
 * Usage:
 * ```vue
 * <script setup lang="ts">
 * import { useImageAuth } from 'src/composables/useImageAuth';
 *
 * const { tokenQueryParam } = useImageAuth();
 * </script>
 *
 * <template>
 *   <q-img
 *     :src="baseUrl + '/' + imagePath + '?' + tokenQueryParam"
 *   />
 * </template>
 * ```
 */
export function useImageAuth() {
  const tokenQueryParam = ref('');
  const authStore = useAuthTokenStore();

  /**
   * Refresh the token query parameter by getting a valid token and org ID
   * This is called automatically on mount and should be called again
   * if the token expires or needs to be refreshed
   */
  async function refreshTokenParam() {
    try {
      const token = await authStore.getValidatedToken();
      if (!token) {
        tokenQueryParam.value = '';
        return;
      }
      const orgId = getOrgId();
      tokenQueryParam.value = `token=${token}&org_id=${orgId}`;
    } catch (error) {
      console.error('Failed to refresh image auth token:', error);
      tokenQueryParam.value = '';
    }
  }

  /**
   * Initialize the token on component mount
   */
  onMounted(() => {
    refreshTokenParam();
  });

  return {
    tokenQueryParam,
    refreshTokenParam,
  };
}
